css:
html,body{margin:0;padding:0}body{background:#f4f5f6}
@font-face {
  font-family: InterVariable;
  src: url("/assets/InterVariable.woff2") format("woff2");
  font-weight: 100 900;
  font-display: swap;
}

/* Shared public pricing section and dedicated pricing page. */
.yaap-landing .pricing-section {
  padding: 88px 0 64px;
  border-top: 1px solid #262c3214;
}
.yaap-landing .pricing-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 40px;
  margin-bottom: 40px;
}
.yaap-landing .pricing-heading h2 {
  max-width: 24ch;
}
.yaap-landing .pricing-heading h1 {
  font-size: 60px;
  letter-spacing: -2.4px;
  line-height: 1.1;
  max-width: 24ch;
}
.yaap-landing .pricing-heading h1 span,
.yaap-landing .pricing-heading h2 span {
  color: #2458eb;
}
.yaap-landing .pricing-heading p {
  max-width: 40ch;
  font-size: 16px;
}
.yaap-landing .pricing-section-page {
  padding-top: 88px;
}
.yaap-landing .pricing-section-page .pricing-heading {
  display: grid;
  gap: 24px;
  margin-bottom: 48px;
}
.yaap-landing .pricing-section-page .pricing-heading p {
  max-width: 56ch;
  font-size: 18px;
}
.yaap-landing .pricing-board {
  display: grid;
  grid-template-columns: minmax(0, 7fr) minmax(0, 4fr);
  border: 1px solid #262c3220;
  border-radius: 10px;
  background: #fff;
  overflow: hidden;
}
.yaap-landing .pricing-configurator {
  padding: 40px;
  min-width: 0;
}
.yaap-landing .pricing-configurator label {
  font-weight: 550;
}
.yaap-landing .pricing-volume {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 12px;
  margin: 16px 0 8px;
  font-variant-numeric: tabular-nums;
}
.yaap-landing .pricing-volume .pricing-event-count {
  font-size: 42px;
  font-weight: 550;
  letter-spacing: -1.4px;
}
.yaap-landing .pricing-volume span {
  color: #67717b;
}
.yaap-landing .pricing-configurator > p {
  font-size: 14px;
  max-width: 56ch;
}
.yaap-landing .pricing-slider {
  margin: 26px 0 24px;
}
.yaap-landing .pricing-slider input {
  display: block;
  appearance: none;
  width: 100%;
  height: 48px;
  margin: 0;
  background: transparent;
  cursor: pointer;
  accent-color: #2458eb;
}
.yaap-landing .pricing-slider input::-webkit-slider-runnable-track {
  height: 6px;
  border-radius: 3px;
  background: linear-gradient(
    to right,
    #2458eb 0%,
    #2458eb var(--pricing-progress),
    #e3e7ef var(--pricing-progress),
    #e3e7ef 100%
  );
}
.yaap-landing .pricing-slider input::-moz-range-track {
  height: 6px;
  border-radius: 3px;
  background: #e3e7ef;
}
.yaap-landing .pricing-slider input::-moz-range-progress {
  height: 6px;
  border-radius: 3px;
  background: #2458eb;
}
.yaap-landing .pricing-slider input::-webkit-slider-thumb {
  appearance: none;
  width: 24px;
  height: 24px;
  margin-top: -9px;
  border: 6px solid #2458eb;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 0 0 4px #2458eb12;
}
.yaap-landing .pricing-slider input::-moz-range-thumb {
  box-sizing: border-box;
  width: 24px;
  height: 24px;
  border: 6px solid #2458eb;
  border-radius: 50%;
  background: #fff;
}
.yaap-landing .pricing-slider input:focus-visible {
  outline: 2px solid #2458eb;
  outline-offset: -1px;
  border-radius: 6px;
}
.yaap-landing .pricing-stops {
  display: flex;
  justify-content: space-between;
  gap: 0;
}
.yaap-landing .pricing-stops button {
  position: relative;
  border: 0;
  background: transparent;
  padding: 8px 0;
  color: #67717b;
  font: inherit;
  font-size: 14px;
  cursor: pointer;
  font-variant-numeric: tabular-nums;
}
.yaap-landing .pricing-stops button::before {
  content: "";
  position: absolute;
  inset: 50% auto auto 50%;
  width: max(100%, 44px);
  height: 48px;
  transform: translate(-50%, -50%);
}
.yaap-landing .pricing-stops button[aria-pressed="true"] {
  color: #2458eb;
  font-weight: 550;
}
.yaap-landing .pricing-stops button:hover {
  color: #2458eb;
}
.yaap-landing .pricing-stops button:focus-visible {
  outline: 2px solid #2458eb;
  outline-offset: 2px;
  border-radius: 3px;
}
.yaap-landing .pricing-total {
  padding: 40px;
  border-left: 1px solid #262c3214;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 28px;
}
.yaap-landing .pricing-total h3 {
  font-size: 18px;
}
.yaap-landing .pricing-price {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin: 12px 0 8px;
  font-variant-numeric: tabular-nums;
}
.yaap-landing .pricing-price > span:first-child {
  font-size: 64px;
  line-height: 1.1;
  font-weight: 550;
  letter-spacing: -2px;
}
.yaap-landing .pricing-price > span:nth-child(2) {
  color: #67717b;
  white-space: nowrap;
}
@media (max-width: 360px) {
  .yaap-landing .pricing-stops button:not(:first-child):not(:last-child) {
    display: none;
  }
  .yaap-landing .pricing-price > span:first-child {
    font-size: 56px;
  }
}
.yaap-landing .pricing-total p {
  font-size: 14px;
}
.yaap-landing .pricing-start {
  display: grid;
  gap: 12px;
}
.yaap-landing .pricing-start .button {
  justify-content: space-between;
}
.yaap-landing .pricing-total .pricing-coming-soon {
  color: #2458eb;
  font-weight: 550;
}
.yaap-landing .pricing-included {
  grid-column: 1 / -1;
  padding: 28px 40px 32px;
  border-top: 1px solid #262c3214;
}
.yaap-landing .pricing-included > p {
  font-size: 14px;
  color: #262c32;
  font-weight: 550;
  margin-bottom: 16px;
}
.yaap-landing .pricing-included ul {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px 28px;
  padding: 0;
  margin: 0;
  list-style: none;
  font-size: 14px;
}
.yaap-landing .pricing-included li {
  display: flex;
  gap: 10px;
  align-items: start;
}
.yaap-landing .pricing-included svg {
  flex-shrink: 0;
  height: 1lh;
  stroke: #2458eb;
}
.yaap-landing .pricing-after {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 20px;
  padding-top: 24px;
  font-size: 14px;
}
.yaap-landing .pricing-after a {
  color: #262c32;
}
.yaap-landing .pricing-after a:hover {
  color: #2458eb;
}
.yaap-landing .pricing-after p a {
  display: inline-block;
  margin-left: 6px;
  text-decoration: underline;
  text-underline-offset: 3px;
}
.yaap-landing .pricing-self-host {
  padding: 64px 0;
  border-top: 1px solid #262c3214;
  border-bottom: 1px solid #262c3214;
}
.yaap-landing .pricing-self-host-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 40px;
}
.yaap-landing .pricing-self-host h2 {
  font-size: 30px;
}
.yaap-landing .pricing-self-host p {
  max-width: 56ch;
  margin-top: 20px;
}
.yaap-landing .pricing-self-host a {
  flex-shrink: 0;
}
.yaap-landing .pricing-faq .faq-grid > div > p {
  max-width: 30ch;
  margin-top: 20px;
}
.yaap-landing .pricing-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}
@media (max-width: 800px) {
  .yaap-landing .pricing-heading {
    display: grid;
    gap: 24px;
  }
  .yaap-landing .pricing-heading h1 {
    font-size: 48px;
  }
  .yaap-landing .pricing-configurator,
  .yaap-landing .pricing-total {
    padding: 28px;
  }
  .yaap-landing .pricing-included {
    padding: 28px;
  }
  .yaap-landing .pricing-included ul {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .yaap-landing .pricing-board {
    grid-template-columns: minmax(0, 1fr);
  }
  .yaap-landing .pricing-total {
    border-left: 0;
    border-top: 1px solid #262c3214;
    flex-direction: row;
    align-items: center;
  }
}
@media (max-width: 500px) {
  .yaap-landing .pricing-section,
  .yaap-landing .pricing-section-page {
    padding: 56px 0 40px;
  }
  .yaap-landing .pricing-heading h1 {
    font-size: 38px;
    letter-spacing: -1.4px;
  }
  .yaap-landing .pricing-heading h2 {
    font-size: 30px;
  }
  .yaap-landing .pricing-heading p,
  .yaap-landing .pricing-section-page .pricing-heading p {
    font-size: 16px;
  }
  .yaap-landing .pricing-configurator,
  .yaap-landing .pricing-total {
    padding: 24px;
  }
  .yaap-landing .pricing-configurator label,
  .yaap-landing .pricing-configurator > p,
  .yaap-landing .pricing-total p,
  .yaap-landing .pricing-included > p,
  .yaap-landing .pricing-included ul,
  .yaap-landing .pricing-after,
  .yaap-landing .pricing-stops button {
    font-size: 16px;
  }
  .yaap-landing .pricing-volume {
    gap: 0 8px;
  }
  .yaap-landing .pricing-volume .pricing-event-count {
    font-size: 36px;
  }
  .yaap-landing .pricing-total {
    flex-direction: column;
    align-items: stretch;
    gap: 24px;
  }
  .yaap-landing .pricing-included {
    padding: 24px;
  }
  .yaap-landing .pricing-included ul {
    grid-template-columns: minmax(0, 1fr);
  }
  .yaap-landing .pricing-self-host-inner {
    flex-direction: column;
    align-items: start;
    gap: 24px;
  }
  .yaap-landing .pricing-self-host p,
  .yaap-landing .pricing-faq p {
    font-size: 16px;
  }
}
.yaap-landing * {
  box-sizing: border-box;
}
.yaap-landing {
  scroll-behavior: auto;
}
.yaap-landing {
  margin: 0;
  background: #f4f5f6;
  color: #262c32;
  font:
    15px/1.55 InterVariable,
    Arial,
    sans-serif;
  -webkit-font-smoothing: antialiased;
  font-feature-settings: "cv02", "cv03", "cv04", "cv11", "ss01", "ss03";
}
.yaap-landing main {
  isolation: isolate;
}
.yaap-landing a {
  color: inherit;
  text-decoration: none;
}
.yaap-landing a:focus-visible,
.yaap-landing summary:focus-visible {
  outline: 2px solid #343a40;
  outline-offset: 5px;
}
.yaap-landing a:hover {
  color: #67717b;
}
.yaap-landing h1,
.yaap-landing h2,
.yaap-landing h3,
.yaap-landing p,
.yaap-landing dl,
.yaap-landing dd {
  margin: 0;
}
.yaap-landing h1,
.yaap-landing h2,
.yaap-landing h3 {
  text-wrap: balance;
  font-weight: 550;
}
.yaap-landing p,
.yaap-landing dd {
  text-wrap: pretty;
  color: #67717b;
}
.yaap-landing h2 {
  font-size: 38px;
  letter-spacing: -1.4px;
  line-height: 1.2;
}
.yaap-landing h3 {
  font-size: 16px;
}
.yaap-landing strong,
.yaap-landing b {
  font-weight: 550;
}
.yaap-landing .wrap {
  width: min(1160px, 100%);
  margin: 0 auto;
  padding: 0 28px;
}
.yaap-landing header {
  border-bottom: 1px solid #262c3210;
}
.yaap-landing .nav {
  height: 88px;
  display: flex;
  align-items: center;
  gap: 36px;
}
.yaap-landing .wordmark {
  font-size: 30px;
  letter-spacing: -1.8px;
  font-weight: 650;
  flex: 1;
}
.yaap-landing .brand-dot {
  color: #67717b;
}
.yaap-landing .nav nav {
  display: flex;
  gap: 32px;
  font-size: 14px;
}
.yaap-landing .nav-end {
  flex: 1;
  text-align: right;
  font-size: 14px;
}
.yaap-landing .mobile-menu {
  display: none;
}
.yaap-landing .hero {
  padding: 68px 0 0;
}
.yaap-landing .eyebrow {
  font-size: 14px;
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: 9px;
  color: #4f5962;
}
.yaap-landing .dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  background: #218057;
  border-radius: 100%;
  flex-shrink: 0;
}
.yaap-landing h1 {
  font-size: 62px;
  line-height: 1.08;
  letter-spacing: -3.1px;
  margin: 25px 0 27px;
  max-width: 30ch;
}
.yaap-landing h1 span {
  color: #67717b;
}
.yaap-landing .hero-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 28px;
}
.yaap-landing .hero-bottom p {
  font-size: 17px;
  max-width: 55ch;
}
.yaap-landing .actions {
  display: flex;
  align-items: center;
  gap: 23px;
  font-size: 14px;
  flex-shrink: 0;
}
.yaap-landing .button {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  padding: 14px 16px;
  border-radius: 8px;
  min-height: 48px;
  font-weight: 500;
}
.yaap-landing .primary {
  background: #343a40;
  color: white;
}
.yaap-landing .primary:hover {
  background: #202529;
  color: white;
}
.yaap-landing .text-link {
  display: inline-flex;
  gap: 15px;
  align-items: center;
  color: #343a40;
  font-weight: 500;
}
.yaap-landing .product-window {
  margin-top: 44px;
  outline: 1px solid #262c3214;
  border-radius: min(1vw, 12px);
  overflow: hidden;
  background: white;
  box-shadow: 0 16px 48px #262c3208;
  scroll-margin-top: 24px;
}
.yaap-landing .window-top {
  height: 40px;
  background: #f7f8f9;
  border-bottom: 1px solid #262c3210;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 19px;
  font-size: 11px;
  color: #67717b;
}
.yaap-landing .sample {
  display: flex;
  gap: 6px;
  align-items: center;
}
.yaap-landing .dashboard {
  display: flex;
  min-height: 555px;
  container-type: inline-size;
}
.yaap-landing .sidebar {
  width: 170px;
  flex-shrink: 0;
  background: #f4f5f6;
  padding: 24px 12px;
  display: flex;
  flex-direction: column;
  gap: 9px;
  font-size: 12px;
  color: #4f5962;
}
.yaap-landing .sidebar > div {
  padding: 8px 10px;
}
.yaap-landing .sidebar .mini-brand {
  font-size: 19px;
  letter-spacing: -0.7px;
  color: #262c32;
  font-weight: 600;
  padding-top: 0;
}
.yaap-landing .site {
  margin: 9px 0;
  background: white;
  border: 1px solid #262c3210;
  border-radius: 8px;
  font-weight: 550;
}
.yaap-landing .site > span,
.yaap-landing .side-active > span {
  float: right;
}
.yaap-landing .site small {
  display: block;
  font-weight: 400;
  color: #67717b;
  font-size: 10px;
}
.yaap-landing .side-active {
  border-radius: 6px;
  background: #e7ebee;
  color: #262c32;
}
.yaap-landing .settings {
  margin-top: 18px;
}
.yaap-landing .sidebar .sidebar-foot {
  margin-top: auto;
  font-size: 10px;
}
.yaap-landing .workspace {
  padding: 27px 28px 23px;
  flex: 1;
  min-width: 0;
}
.yaap-landing .dash-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.yaap-landing .dash-heading p {
  font-size: 11px;
}
.yaap-landing .dash-heading h2 {
  font-size: 25px;
  letter-spacing: -1px;
  margin-top: 2px;
}
.yaap-landing .period {
  padding: 7px 9px;
  border: 1px solid #262c3214;
  border-radius: 6px;
  font-size: 11px;
  display: flex;
  gap: 20px;
}
.yaap-landing .tabs {
  display: flex;
  gap: 25px;
  border-bottom: 1px solid #262c3212;
  margin: 18px 0 20px;
  font-size: 11px;
  color: #67717b;
}
.yaap-landing .tabs > * {
  padding: 8px 0;
}
.yaap-landing .tabs strong {
  border-bottom: 2px solid #343a40;
  color: #262c32;
}
.yaap-landing .metrics {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  font-variant-numeric: tabular-nums;
}
.yaap-landing .metrics > div {
  padding: 10px 12px;
  background: #f7f8f9;
  border-radius: 7px;
  min-width: 0;
}
.yaap-landing .metrics dt {
  font-size: 10px;
  white-space: nowrap;
  color: #4f5962;
}
.yaap-landing .metrics dd {
  color: #262c32;
  font-size: 25px;
  letter-spacing: -0.7px;
  margin-top: 5px;
}
.yaap-landing .metrics small {
  display: block;
  color: #218057;
  font-size: 9px;
  letter-spacing: 0;
}
.yaap-landing .chart-head {
  display: flex;
  justify-content: space-between;
  margin: 20px 0 13px;
  font-size: 12px;
}
.yaap-landing .chart-head span {
  color: #67717b;
  font-size: 10px;
}
.yaap-landing .chart {
  display: flex;
  gap: 16px;
  height: 139px;
}
.yaap-landing .chart svg {
  flex: 1;
  min-width: 0;
}
.yaap-landing .axis {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  color: #67717b;
  font-size: 9px;
  width: 16px;
}
.yaap-landing .grid {
  stroke: #262c320a;
  fill: none;
}
.yaap-landing .area {
  fill: #343a4008;
}
.yaap-landing .current {
  stroke: #343a40;
  stroke-width: 2;
  fill: none;
}
.yaap-landing .previous {
  stroke: #b6bdc4;
  stroke-width: 1.3;
  stroke-dasharray: 5 5;
  fill: none;
}
.yaap-landing .dates {
  display: flex;
  justify-content: space-between;
  padding-left: 32px;
  margin-top: 8px;
  font-size: 9px;
  color: #67717b;
}
.yaap-landing .report-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 28px;
  margin-top: 22px;
  padding-top: 16px;
  border-top: 1px solid #262c3210;
}
.yaap-landing .report-grid h3 {
  font-size: 13px;
  margin-bottom: 10px;
}
.yaap-landing .table-row {
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  padding: 5px 0;
  border-bottom: 1px solid #262c3208;
  font-variant-numeric: tabular-nums;
}
.yaap-landing .table-label {
  color: #67717b;
  font-size: 9px;
}
.yaap-landing .proof-strip {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding: 25px 0 30px;
  font-size: 13px;
  color: #67717b;
}
.yaap-landing .features {
  background: white;
  border-top: 1px solid #262c3210;
  padding: 67px 0;
}
.yaap-landing .section-heading h2 {
  margin-top: 14px;
}
.yaap-landing .feature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
  margin-top: 37px;
}
.yaap-landing .feature-grid > div {
  min-width: 0;
  border-top: 1px solid #262c321a;
  padding-top: 22px;
}
.yaap-landing .feature-number {
  font: 10px/1.5 monospace;
  letter-spacing: 1px;
  color: #67717b;
}
.yaap-landing .feature-grid dt {
  font-size: 20px;
  font-weight: 550;
  letter-spacing: -0.6px;
  margin: 15px 0 8px;
}
.yaap-landing .feature-grid dd {
  font-size: 14px;
  max-width: 36ch;
  min-height: 66px;
}
.yaap-landing .mini-report,
.yaap-landing .funnel,
.yaap-landing .revenue {
  height: 148px;
  background: #f7f8f9;
  padding: 16px 18px;
  border-radius: 8px;
  margin-top: 20px;
  font-size: 11px;
}
