/* Yaap brand accent: cobalt blue over the existing Graphite foundation. */
.yaap-landing {
  --brand: #2458eb;
  --brand-hover: #1945c7;
  --brand-soft: #edf2ff;
  --brand-mid: #8faafa;
}
.yaap-landing .brand-dot,
.yaap-landing h1 em {
  color: var(--brand);
}
.yaap-landing h1 em {
  font-style: normal;
}
.yaap-landing .hero > .wrap > .eyebrow .dot {
  background: var(--brand);
}
.yaap-landing .primary {
  background: var(--brand);
  box-shadow: 0 2px 3px #1745cd1a;
}
.yaap-landing .primary:hover {
  background: var(--brand-hover);
}
.yaap-landing a:focus-visible,
.yaap-landing summary:focus-visible {
  outline-color: var(--brand);
}
.yaap-landing .text-link:hover,
.yaap-landing .nav a:hover {
  color: var(--brand);
}
.yaap-landing .side-active {
  background: var(--brand-soft);
  color: #2348a8;
}
.yaap-landing .tabs strong {
  border-bottom-color: var(--brand);
}
.yaap-landing .current {
  stroke: var(--brand);
  stroke-width: 2.25;
}
.yaap-landing .area {
  fill: #2458eb0b;
}
.yaap-landing .metrics > div:first-child {
  background: var(--brand-soft);
}
.yaap-landing .feature-number {
  color: #2453c7;
}
.yaap-landing .bar-one {
  background: var(--brand);
}
.yaap-landing .bar-two {
  background: #7898f4;
}
.yaap-landing .bar-three {
  background: #b2c3f9;
}
.yaap-landing .funnel > div {
  background: #edf2ff;
  border-left-color: var(--brand);
}
.yaap-landing .revenue > div:not(.receipt) {
  color: #2453c7;
}
.yaap-landing .architecture {
  background: #1745cd;
  border: 1px solid #1745cd;
  color: white;
}
.yaap-landing .architecture-title {
  color: #ffffffb8;
}
.yaap-landing .worker {
  background: #ffffff;
  border-color: #ffffff20;
  color: #262c32;
