.yaap-landing .skip-link {
  position: absolute;
  left: 20px;
  top: 12px;
  z-index: 20;
  padding: 8px 12px;
  background: white;
  transform: translateY(-200%);
}
.yaap-landing .skip-link:focus {
  transform: none;
}
.yaap-landing .button,
