  position: relative;
}
@media (pointer: coarse) {
  .yaap-landing .button::after,
  .yaap-landing .github-button::after {
    content: "";
    position: absolute;
    inset: -6px 0;
  }
}

/* Pointer feedback is brief; keyboard navigation and reduced motion stay instant. */
@media (prefers-reduced-motion: no-preference) and (hover: hover) and (pointer: fine) {
  .yaap-landing .button {
    transition: transform 140ms cubic-bezier(0.22, 1, 0.36, 1);
  }
  .yaap-landing .button:active:not(:focus-visible) {
    transform: scale(0.98);
  }
  .yaap-landing .button > span,
  .yaap-landing .text-link > span {
    display: inline-block;
    transition: transform 180ms cubic-bezier(0.22, 1, 0.36, 1);
  }
  .yaap-landing .button:hover > span,
  .yaap-landing .ownership .text-link:hover > span {
    transform: translate(2px, -2px);
  }
  .yaap-landing .hero .text-link:hover > span {
    transform: translateY(2px);
  }
}

